export const envelope = [15, 25, 23];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 4;

  const wood = api.theme.wood;
  const basePlanks = (wood.planks || "minecraft:oak_planks").replace(/\[.*\]/, "");
  const baseLog = (wood.log || "minecraft:oak_log").replace(/\[.*\]/, "");
  const baseStripped = (wood.stripped || "minecraft:stripped_oak_log").replace(/\[.*\]/, "");
  const baseStairs = (wood.stairs || "minecraft:oak_stairs").replace(/\[.*\]/, "");
  const baseSlab = (wood.slab || "minecraft:oak_slab").replace(/\[.*\]/, "");
  const baseFence = (wood.fence || "minecraft:oak_fence").replace(/\[.*\]/, "");
  const baseTrapdoor = (wood.trapdoor || "minecraft:oak_trapdoor").replace(/\[.*\]/, "");

  function stLog(axis = "y") {
    return `${baseLog}[axis=${axis}]`;
  }
  function stStripped(axis = "y") {
    return `${baseStripped}[axis=${axis}]`;
  }
  function stStairs(facing = "north", half = "bottom", shape = "straight") {
    return `${baseStairs}[facing=${facing},half=${half},shape=${shape}]`;
  }
  function stSlab(type = "bottom") {
    return `${baseSlab}[type=${type}]`;
  }
  function stTrapdoor(facing = "north", half = "bottom", open = false) {
    return `${baseTrapdoor}[facing=${facing},half=${half},open=${open ? "true" : "false"}]`;
  }

  function set(x, y, z, block) {
    x = Math.floor(x);
    y = Math.floor(y);
    z = Math.floor(z);
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // --- Ground Conformation Helper (Rule 6) ---
  function groundSupport(x, z, startY) {
    const gh = seatY + api.heightAt(x, z);
    const targetY = Math.max(0, Math.min(H - 1, gh));
    if (targetY < startY) {
      for (let y = targetY; y <= startY; y++) {
        set(x, y, z, stLog("y"));
      }
    } else if (targetY > startY) {
      for (let y = startY; y <= targetY; y++) {
        set(x, y, z, basePlanks);
      }
    } else {
      set(x, startY, z, stLog("y"));
    }
  }

  // ==========================================
  // 1. WHEELED CHASSIS & PLATFORM CARRIAGE
  // ==========================================

  // Axle Beams & Axle Hubs
  const axleZs = [5, 11, 17];
  for (const az of axleZs) {
    for (let x = 2; x <= 12; x++) {
      set(x, 4, az, stLog("x"));
    }
    // Axle pins / hub caps
    set(0, 4, az, baseFence);
    set(14, 4, az, baseFence);
  }

  // 6 Heavy Cart Wheels (3x3 circular discs)
  function buildWheel(centerX, centerZ) {
    const xOffsets = centerX <= 2 ? [1, 2] : [12, 13];
    for (const wx of xOffsets) {
      // Hub
      set(wx, 4, centerZ, stLog("x"));
      // Rims
      set(wx, 5, centerZ, stStripped("z"));
      set(wx, 3, centerZ, stStripped("z"));
      set(wx, 4, centerZ - 1, stStripped("y"));
      set(wx, 4, centerZ + 1, stStripped("y"));

      // Curved corners
      set(wx, 5, centerZ - 1, stStairs("south", "top"));
      set(wx, 5, centerZ + 1, stStairs("north", "top"));
      set(wx, 3, centerZ - 1, stStairs("south", "bottom"));
      set(wx, 3, centerZ + 1, stStairs("north", "bottom"));

      // Ground supports below the wheel rim
      for (let dz = -1; dz <= 1; dz++) {
        groundSupport(wx, centerZ + dz, 3);
      }
    }
  }

  for (const az of axleZs) {
    buildWheel(1, az);
    buildWheel(13, az);
  }

  // Longitudinal chassis beams (Y = 5)
  for (let z = 3; z <= 19; z++) {
    set(3, 5, z, stStripped("z"));
    set(5, 5, z, stLog("z"));
    set(7, 5, z, stLog("z"));
    set(9, 5, z, stLog("z"));
    set(11, 5, z, stLog("z"));
  }

  // Transverse frame crossbeams (Y = 5)
  for (const fz of [3, 5, 8, 11, 14, 17, 19]) {
    for (let x = 3; x <= 11; x++) {
      set(x, 5, fz, stLog("x"));
    }
    // Ground skids
    groundSupport(3, fz, 4);
    groundSupport(11, fz, 4);
  }

  // Chassis Deck Planking (Y = 6)
  for (let x = 3; x <= 11; x++) {
    for (let z = 4; z <= 18; z++) {
      set(x, 6, z, basePlanks);
    }
  }

  // Chassis perimeter deck rails & tie-downs
  for (let z = 3; z <= 19; z++) {
    set(3, 7, z, stSlab("bottom"));
    set(11, 7, z, stSlab("bottom"));
  }
  for (let x = 4; x <= 10; x++) {
    set(x, 7, 3, stSlab("bottom"));
    set(x, 7, 19, stSlab("bottom"));
  }

  // Towing bollards / hitch ropes at cart front
  set(4, 7, 3, baseFence);
  set(6, 7, 3, baseFence);
  set(8, 7, 3, baseFence);
  set(10, 7, 3, baseFence);

  // ==========================================
  // 2. HORSE'S LEGS & TIMBER STRUTS
  // ==========================================

  const legPositions = [
    { x1: 4, x2: 5, z1: 6, z2: 7, front: true },    // Front-Left
    { x1: 9, x2: 10, z1: 6, z2: 7, front: true },   // Front-Right
    { x1: 4, x2: 5, z1: 15, z2: 16, front: false }, // Rear-Left
    { x1: 9, x2: 10, z1: 15, z2: 16, front: false } // Rear-Right
  ];

  for (const leg of legPositions) {
    // Hooves & lower base (Y = 6..7)
    for (let x = leg.x1; x <= leg.x2; x++) {
      for (let z = leg.z1; z <= leg.z2; z++) {
        set(x, 6, z, stLog("y"));
        set(x, 7, z, stStripped("y"));
      }
    }

    // Hoof trim stairs
    set(leg.x1, 6, leg.z1 - 1, stStairs("south", "bottom"));
    set(leg.x2, 6, leg.z1 - 1, stStairs("south", "bottom"));
    set(leg.x1, 6, leg.z2 + 1, stStairs("north", "bottom"));
    set(leg.x2, 6, leg.z2 + 1, stStairs("north", "bottom"));

    // Knee / Hock joints (Y = 8)
    for (let x = leg.x1; x <= leg.x2; x++) {
      for (let z = leg.z1; z <= leg.z2; z++) {
        set(x, 8, z, stStripped("y"));
      }
    }
    if (leg.front) {
      set(leg.x1, 8, leg.z1, stLog("z"));
      set(leg.x2, 8, leg.z1, stLog("z"));
    } else {
      set(leg.x1, 8, leg.z2, stLog("z"));
      set(leg.x2, 8, leg.z2, stLog("z"));
    }

    // Upper Leg / Thighs (Y = 9..10)
    for (let y = 9; y <= 10; y++) {
      for (let x = leg.x1; x <= leg.x2; x++) {
        for (let z = leg.z1; z <= leg.z2; z++) {
          set(x, y, z, stStripped("y"));
        }
      }
    }

    // Rear thigh muscular expansion
    if (!leg.front) {
      for (let x = leg.x1; x <= leg.x2; x++) {
        set(x, 10, leg.z1 - 1, basePlanks);
        set(x, 10, leg.z2 + 1, basePlanks);
      }
    }
  }

  // Diagonal leg-to-deck timber braces
  set(4, 7, 5, stStairs("north", "bottom"));
  set(5, 7, 5, stStairs("north", "bottom"));
  set(9, 7, 5, stStairs("north", "bottom"));
  set(10, 7, 5, stStairs("north", "bottom"));

  set(4, 7, 17, stStairs("south", "bottom"));
  set(5, 7, 17, stStairs("south", "bottom"));
  set(9, 7, 17, stStairs("south", "bottom"));
  set(10, 7, 17, stStairs("south", "bottom"));

  // ==========================================
  // 3. HOLLOW SHIP-HULL TORSO (BELLY & RIBS)
  // ==========================================

  // Floor of the belly (Y = 11)
  for (let z = 5; z <= 17; z++) {
    for (let x = 4; x <= 10; x++) {
      set(x, 11, z, basePlanks);
    }
    set(7, 11, z, stLog("z")); // Keelson spine
  }

  // Torso Walls & Outer Barrel Hull (Y = 12..16)
  for (let y = 12; y <= 16; y++) {
    for (let z = 4; z <= 18; z++) {
      for (let x = 3; x <= 11; x++) {
        const isOuterWall = (x === 3 || x === 11 || z === 4 || z === 18 ||
                             ((x === 4 || x === 10) && (z === 5 || z === 17)));
        if (isOuterWall) {
          // Ship frame ribbing at intervals
          if (z === 5 || z === 8 || z === 11 || z === 14 || z === 17) {
            set(x, y, z, stLog("y"));
          } else {
            set(x, y, z, basePlanks);
          }
        }
      }
    }
  }

  // External plank smoothing with stairs on belly curves
  for (let z = 5; z <= 17; z++) {
    set(3, 12, z, stStairs("east", "bottom"));
    set(11, 12, z, stStairs("west", "bottom"));
    set(3, 16, z, stStairs("east", "top"));
    set(11, 16, z, stStairs("west", "top"));
  }

  // Look-out peepholes for hidden warriors
  set(3, 14, 11, baseFence);
  set(11, 14, 11, baseFence);
  set(7, 14, 4, baseFence);

  // Dorsal Back & Spine (Y = 17..18)
  for (let z = 5; z <= 17; z++) {
    for (let x = 5; x <= 9; x++) {
      set(x, 17, z, basePlanks);
    }
    set(7, 17, z, stLog("z"));
    set(5, 17, z, stStairs("west", "bottom"));
    set(9, 17, z, stStairs("east", "bottom"));
  }

  for (let z = 6; z <= 16; z++) {
    set(6, 18, z, stSlab("bottom"));
    set(7, 18, z, stStripped("z"));
    set(8, 18, z, stSlab("bottom"));
  }

  // ==========================================
  // 4. SECRET BELLY TRAPDOOR & LADDER RUNGS
  // ==========================================

  // The secret hatch opening at underbelly (7, 11, 11)
  set(7, 11, 11, stTrapdoor("north", "bottom", true));
  set(7, 6, 11, stTrapdoor("north", "bottom", true));

  // Center vertical ladder shaft and rungs
  for (let y = 3; y <= 11; y++) {
    set(7, y, 10, stLog("y"));
    set(7, y, 11, "minecraft:ladder[facing=north]");
  }
  groundSupport(7, 10, 3);

  // ==========================================
  // 5. CHEST, SHOULDERS, & PROW
  // ==========================================

  for (let y = 12; y <= 16; y++) {
    set(6, y, 3, stStairs("south", "bottom"));
    set(7, y, 3, stLog("y"));
    set(8, y, 3, stStairs("south", "bottom"));
  }
  // Ship ram / breast ornament
  set(7, 13, 2, stStairs("north", "bottom"));
  set(7, 14, 2, stLog("z"));
  set(7, 15, 2, stStairs("north", "top"));

  // ==========================================
  // 6. NECK & HEAD (Facing North -Z)
  // ==========================================

  // Neck Base (Y = 16..18)
  for (let x = 6; x <= 8; x++) {
    for (let z = 3; z <= 5; z++) {
      set(x, 16, z, stStripped("y"));
      set(x, 17, z, stStripped("y"));
    }
    for (let z = 2; z <= 4; z++) {
      set(x, 18, z, stStripped("y"));
    }
  }

  // Mid Neck (Y = 19..20)
  for (let x = 6; x <= 8; x++) {
    for (let z = 1; z <= 4; z++) {
      set(x, 19, z, basePlanks);
    }
    for (let z = 1; z <= 3; z++) {
      set(x, 20, z, basePlanks);
    }
  }

  // Throat & Lower Muzzle (Y = 20..21)
  for (let x = 6; x <= 8; x++) {
    set(x, 20, 0, stStripped("z"));
    set(x, 20, 1, basePlanks);
    set(x, 20, 2, stStairs("north", "top"));

    set(x, 21, 0, stStripped("z"));
    set(x, 21, 1, stStripped("z"));
    set(x, 21, 2, basePlanks);
    set(x, 21, 3, stLog("z"));
  }

  // Forehead, Brow, & Eyes (Y = 22)
  for (let x = 6; x <= 8; x++) {
    set(x, 22, 1, basePlanks);
    set(x, 22, 2, stStripped("y"));
    set(x, 22, 3, stLog("z"));
  }
  // Eye sockets
  set(5, 22, 2, stStairs("south", "bottom"));
  set(9, 22, 2, stStairs("south", "bottom"));

  // Head Crown & Ears (Y = 23..24)
  for (let x = 6; x <= 8; x++) {
    set(x, 23, 2, stSlab("bottom"));
    set(x, 23, 3, stLog("z"));
  }
  // Left and Right Ears
  set(6, 23, 3, stStairs("north", "bottom"));
  set(8, 23, 3, stStairs("north", "bottom"));
  set(6, 24, 3, baseFence);
  set(8, 24, 3, baseFence);

  // Dorsal Timber Mane
  set(7, 23, 4, stStairs("north", "top"));
  set(7, 22, 4, stStripped("z"));
  set(7, 21, 4, stStairs("north", "top"));
  set(7, 20, 4, stStripped("z"));
  set(7, 19, 5, stStairs("north", "top"));
  set(7, 18, 5, stStripped("z"));
  set(7, 17, 6, stStairs("north", "top"));

  // ==========================================
  // 7. ARCHING TIMBER TAIL
  // ==========================================

  set(7, 17, 18, stLog("z"));
  set(7, 16, 19, stLog("z"));
  set(7, 15, 20, stStripped("y"));
  set(7, 14, 20, stLog("y"));
  set(6, 14, 20, stStairs("east", "top"));
  set(8, 14, 20, stStairs("west", "top"));
  set(7, 13, 21, stStripped("y"));
  set(7, 12, 21, stStripped("y"));
  set(7, 11, 21, stLog("y"));
  set(7, 10, 22, stStripped("y"));
  set(7, 9, 22, baseFence);
  set(7, 8, 22, baseFence);

  return {
    name: "trojan_horse",
    seatY: seatY,
    anchors: {
      front: [7, 21, 0],
      door: [7, 6, 11]
    },
    interiors: [
      {
        min: [5, 12, 6],
        max: [9, 16, 16],
        kind: "hall"
      }
    ]
  };
}

abandoned_greek_camp.source:
export const envelope = [11, 14, 11];

export default function build(api) {
  const [W, H, D] = api.size;
  const SEAT_Y = 4;
  const rng = () => api.random();

  // -------------------------------------------------------------------------
  // PALETTE SELECTION (Extracted cleanly from api.theme)
  // -------------------------------------------------------------------------
  const t = api.theme;
  const woodLog = t?.wood?.log || "minecraft:oak_log";
  const woodPlanks = t?.wood?.planks || "minecraft:oak_planks";
  const woodStripped = t?.wood?.stripped || "minecraft:stripped_oak_log";
  const woodFence = t?.wood?.fence || "minecraft:oak_fence";
  const woodSlab = t?.wood?.slab || "minecraft:oak_slab";
  const woodStairs = t?.wood?.stairs || "minecraft:oak_stairs";
  const woodTrapdoor = t?.wood?.trapdoor || "minecraft:oak_trapdoor";

  const stonePrimary = t?.stone?.primary || "minecraft:sandstone";
  const stoneAccent = t?.stone?.accent || "minecraft:cut_sandstone";
  const stoneWall = t?.stone?.wall || "minecraft:sandstone_wall";
  const stoneSlab = t?.stone?.slab || "minecraft:sandstone_slab";
  const stoneStairs = t?.stone?.stairs || "minecraft:sandstone_stairs";

  const groundPavement = t?.ground?.pavement || "minecraft:coarse_dirt";
  const groundBank = t?.ground?.bank || "minecraft:dirt";
  const groundScree = t?.ground?.scree || "minecraft:gravel";
  const groundRevetment = t?.ground?.revetment || "minecraft:cobblestone";
  const groundPlinth = t?.ground?.plinth || "minecraft:stone_bricks";

  const roofSolid = t?.roof?.solid || "minecraft:terracotta";
  const roofSlab = t?.roof?.slab || "minecraft:cut_sandstone_slab";
  const roofStairs = t?.roof?.stairs || "minecraft:sandstone_stairs";

  // Helper blockstate formatters
  const makeStair = (base, facing, half = "bottom") =>
    `${base.split("[")[0]}[facing=${facing},half=${half}]`;
  const makeLog = (base, axis = "y") =>
    `${base.split("[")[0]}[axis=${axis}]`;
  const makeSlab = (base, type = "bottom") =>
    `${base.split("[")[0]}[type=${type}]`;
  const makeTrapdoor = (base, facing = "north", open = false, half = "bottom") =>
    `${base.split("[")[0]}[facing=${facing},half=${half},open=${open}]`;

  // Safe setter bounded by envelope
  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Pre-calculate ground heights for footprint
  const ground = Array(W).fill(0).map(() => Array(D).fill(SEAT_Y));
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const h = api.heightAt(x, z);
      ground[x][z] = Math.max(0, Math.min(SEAT_Y + 2, Math.round(SEAT_Y + h)));
    }
  }

  // Determine plugin archetype & symmetry variation
  const archetypeNames = [
    "Deserted Achaean Command Pavilion",
    "Abandoned Shoreline Signal Watchpost",
    "Beached Galley Slipway & Oar Depot",
    "Cold Greek Camp Hearth & Mess Quarters",
    "Abandoned Siege Palisade & Redoubt",
    "Deserted Myrmidon Bivouac & Armory",
  ];
  const archetype = api.instance.index % 6;
  const flipX = rng() < 0.5;

  function mapX(x) {
    return flipX ? (W - 1 - x) : x;
  }

  function setAt(x, y, z, block) {
    set(mapX(x), y, z, block);
  }

  // -------------------------------------------------------------------------
  // 1. CONFORMING EARTHWORK / CAMP PLATFORM (Connected 6-Solid Base)
  // -------------------------------------------------------------------------
  for (let x = 1; x <= 9; x++) {
    for (let z = 1; z <= 9; z++) {
      const gh = ground[mapX(x)][z];
      const topY = Math.max(gh, SEAT_Y);
      const minY = Math.min(gh, SEAT_Y);

      // Foundation fill down to terrain (conforming to flat, slope, ridge, shore)
      for (let y = minY; y < topY; y++) {
        const subBlock = rng() < 0.6 ? groundBank : (rng() < 0.5 ? groundRevetment : stonePrimary);
        setAt(x, y, z, subBlock);
      }

      // Camp ground surface texture
      let surfaceBlock;
      const distFromCenter = Math.hypot(x - 5, z - 5);
      const r = rng();
      if (distFromCenter < 2.5) {
        surfaceBlock = r < 0.45 ? groundPavement : (r < 0.7 ? woodPlanks : groundScree);
      } else if (distFromCenter < 4.0) {
        surfaceBlock = r < 0.5 ? groundPavement : (r < 0.8 ? groundScree : groundBank);
      } else {
        surfaceBlock = r < 0.4 ? groundRevetment : (r < 0.7 ? groundBank : groundScree);
      }
      setAt(x, topY, z, surfaceBlock);
    }
  }

  // -------------------------------------------------------------------------
  // 2. ARCHETYPE SPECIFIC STRUCTURES & DEBRIS
  // -------------------------------------------------------------------------
  const baseY = SEAT_Y + 1;

  if (archetype === 0) {
    // === ARCHETYPE 0: COMMAND PAVILION ===
    // Low perimeter stone retaining wall
    for (let x = 2; x <= 8; x++) {
      setAt(x, baseY, 2, stoneWall);
      setAt(x, baseY, 8, stoneWall);
    }
    for (let z = 3; z <= 7; z++) {
      setAt(2, baseY, z, stoneWall);
      setAt(8, baseY, z, stoneWall);
    }
    setAt(5, baseY, 2, groundPavement); // Front gap

    // 4 Corner Timber Posts
    const corners = [[2, 2], [8, 2], [2, 8], [8, 8]];
    for (const [cx, cz] of corners) {
      for (let y = baseY; y <= SEAT_Y + 4; y++) {
        setAt(cx, y, cz, woodLog);
      }
    }

    // Central High Ridge Posts & Beam (Reaching Y=SEAT_Y+7)
    for (let y = baseY; y <= SEAT_Y + 7; y++) {
      setAt(5, y, 2, woodLog);
      setAt(5, y, 8, woodLog);
    }
    for (let z = 2; z <= 8; z++) {
      setAt(5, SEAT_Y + 7, z, makeLog(woodLog, "z"));
    }

    // Stripped Tent Rafters & Torn Canvas Remnants
    for (let z = 3; z <= 7; z++) {
      setAt(4, SEAT_Y + 6, z, makeStair(woodStairs, flipX ? "west" : "east", "top"));
      setAt(6, SEAT_Y + 6, z, makeStair(woodStairs, flipX ? "east" : "west", "top"));
      setAt(3, SEAT_Y + 5, z, woodSlab);
      setAt(7, SEAT_Y + 5, z, woodSlab);

      // Torn canvas traces
      if (rng() < 0.55) setAt(4, SEAT_Y + 7, z, roofSlab);
      if (rng() < 0.45) setAt(6, SEAT_Y + 7, z, roofSlab);
      if (rng() < 0.35) setAt(3, SEAT_Y + 6, z, makeTrapdoor(woodTrapdoor, "north", false, "bottom"));
    }

    // Entrance Signal Poles
    for (let y = baseY; y <= SEAT_Y + 6; y++) {
      setAt(3, y, 1, woodLog);
      setAt(7, y, 1, woodLog);
    }
    setAt(3, SEAT_Y + 7, 1, woodFence);
    setAt(7, SEAT_Y + 7, 1, woodFence);
    setAt(3, SEAT_Y + 6, 0, "minecraft:chain[axis=y]");
    setAt(7, SEAT_Y + 6, 0, "minecraft:chain[axis=y]");

    // Interior Table, Chests & Debris
    setAt(5, baseY, 5, groundPlinth);
    setAt(5, baseY + 1, 5, woodSlab);
    setAt(5, baseY, 4, makeStair(woodStairs, "south"));
    setAt(4, baseY, 7, "minecraft:chest[facing=north]");
    setAt(6, baseY, 7, "minecraft:barrel[facing=up]");
    setAt(7, baseY, 6, "minecraft:barrel[facing=north]");
    setAt(3, baseY, 5, woodFence);
    setAt(3, baseY + 1, 5, "minecraft:iron_bars");
    setAt(5, baseY, 2, "minecraft:campfire[lit=false]");

  } else if (archetype === 1) {
    // === ARCHETYPE 1: SHORELINE SIGNAL WATCHPOST ===
    // 4 Heavy Tower Leg Pillars (Reaching Y=SEAT_Y+7)
    const towerPosts = [[3, 3], [7, 3], [3, 7], [7, 7]];
    for (const [tx, tz] of towerPosts) {
      for (let y = baseY; y <= SEAT_Y + 7; y++) {
        setAt(tx, y, tz, woodLog);
      }
    }

    // Cross-bracing
    for (let x = 3; x <= 7; x++) {
      setAt(x, SEAT_Y + 3, 3, woodFence);
      setAt(x, SEAT_Y + 3, 7, woodFence);
    }
    for (let z = 3; z <= 7; z++) {
      setAt(3, SEAT_Y + 3, z, woodFence);
      setAt(7, SEAT_Y + 3, z, woodFence);
    }

    // Upper Sentry Watch Platform at SEAT_Y+5
    for (let x = 3; x <= 7; x++) {
      for (let z = 3; z <= 7; z++) {
        setAt(x, SEAT_Y + 5, z, woodPlanks);
      }
    }

    // Watch Parapet
    for (let x = 3; x <= 7; x++) {
      setAt(x, SEAT_Y + 6, 3, woodFence);
      setAt(x, SEAT_Y + 6, 7, woodFence);
    }
    for (let z = 3; z <= 7; z++) {
      setAt(3, SEAT_Y + 6, z, woodFence);
      setAt(7, SEAT_Y + 6, z, woodFence);
    }

    // Central Signal Brazier & Tall Signal Mast (Reaching Y=SEAT_Y+8)
    setAt(5, SEAT_Y + 6, 5, stoneWall);
    setAt(5, SEAT_Y + 7, 5, "minecraft:campfire[lit=false]");
    setAt(5, SEAT_Y + 8, 5, "minecraft:iron_bars");
    setAt(5, SEAT_Y + 8, 4, woodFence);
    setAt(5, SEAT_Y + 8, 6, woodFence);

    // North Shore Palisade Stakes
    for (let x = 2; x <= 8; x++) {
      const stakeH = 2 + ((x * 3) % 3);
      for (let y = baseY; y < baseY + stakeH; y++) {
        setAt(x, y, 1, woodLog);
      }
      setAt(x, baseY + stakeH, 1, woodFence);
    }

    // Ground Sentry Bivouac & Supplies
    setAt(4, baseY, 5, "minecraft:barrel[facing=up]");
    setAt(5, baseY, 5, "minecraft:barrel[facing=north]");
    setAt(6, baseY, 5, "minecraft:chest[facing=south]");
    setAt(3, baseY, 4, woodFence);
    setAt(3, baseY + 1, 4, "minecraft:iron_bars");
    setAt(2, baseY, 5, "minecraft:campfire[lit=false]");
    setAt(2, baseY, 6, "minecraft:gravel");

  } else if (archetype === 2) {
    // === ARCHETYPE 2: SHIPWRIGHT SLIPWAY & GALLEY KEEL ===
    // Timber Skidway Runners embedded across ground
    for (const z of [2, 4, 6, 8]) {
      for (let x = 2; x <= 8; x++) {
        setAt(x, baseY, z, makeLog(woodStripped, "x"));
      }
    }

    // Galley Keel & Stempost
    for (let z = 2; z <= 8; z++) {
      setAt(5, baseY + 1, z, makeLog(woodLog, "z"));
    }
    // High Prow Post
    for (let y = baseY + 2; y <= SEAT_Y + 6; y++) {
      setAt(5, y, 2, woodLog);
    }
    setAt(5, SEAT_Y + 7, 2, woodFence);

    // Curved Hull Ribs
    for (const z of [3, 5, 7]) {
      setAt(4, baseY + 1, z, woodPlanks);
      setAt(6, baseY + 1, z, woodPlanks);
      setAt(3, baseY + 2, z, makeStair(woodStairs, flipX ? "west" : "east"));
      setAt(7, baseY + 2, z, makeStair(woodStairs, flipX ? "east" : "west"));
      setAt(3, baseY + 3, z, woodFence);
      setAt(7, baseY + 3, z, woodFence);
    }

    // Tall Shear-Legs Hoisting Derrick (Reaching Y=SEAT_Y+8)
    for (let y = baseY; y <= SEAT_Y + 7; y++) {
      setAt(2, y, 4, woodLog);
      setAt(2, y, 7, woodLog);
    }
    setAt(2, SEAT_Y + 8, 4, woodFence);
    setAt(2, SEAT_Y + 8, 7, woodFence);
    for (let z = 4; z <= 7; z++) {
      setAt(2, SEAT_Y + 7, z, makeLog(woodLog, "z"));
    }
    setAt(3, SEAT_Y + 8, 5, woodFence);
    setAt(4, SEAT_Y + 8, 5, woodFence);
    setAt(4, SEAT_Y + 7, 5, "minecraft:chain[axis=y]");
    setAt(4, SEAT_Y + 6, 5, "minecraft:chain[axis=y]");

    // Pitch Boiling Hearth & Barrel Depot
    setAt(8, baseY, 3, stonePrimary);
    setAt(8, baseY, 4, "minecraft:campfire[lit=false]");
    setAt(8, baseY + 1, 4, "minecraft:cauldron");
    setAt(8, baseY, 6, "minecraft:barrel[facing=up]");
    setAt(8, baseY, 7, "minecraft:barrel[facing=north]");
    setAt(8, baseY + 1, 6, "minecraft:barrel[facing=up]");
    setAt(7, baseY, 7, "minecraft:hay_block[axis=y]");

  } else if (archetype === 3) {
    // === ARCHETYPE 3: HEARTH, MESS & PROVISIONS DEPOT ===
    // Central Sunken Firepit (4..6, 4..6)
    for (let x = 4; x <= 6; x++) {
      for (let z = 4; z <= 6; z++) {
        setAt(x, baseY, z, "minecraft:basalt");
      }
    }
    setAt(5, baseY, 5, "minecraft:campfire[lit=false]");
    setAt(4, baseY, 5, "minecraft:gravel");
    setAt(6, baseY, 5, "minecraft:gravel");
    setAt(5, baseY, 4, stoneWall);
    setAt(5, baseY, 6, stoneWall);
    setAt(4, baseY, 4, stoneWall);
    setAt(6, baseY, 6, stoneWall);

    // Roasting Spit Tripod & High Awning Spar (Reaching Y=SEAT_Y+8)
    for (let y = baseY + 1; y <= SEAT_Y + 5; y++) {
      setAt(4, y, 4, woodFence);
      setAt(6, y, 4, woodFence);
      setAt(5, y, 7, woodFence);
    }
    setAt(5, SEAT_Y + 6, 5, woodLog);
    setAt(5, SEAT_Y + 7, 5, woodFence);
    setAt(5, SEAT_Y + 8, 5, woodFence);
    setAt(4, SEAT_Y + 8, 5, woodFence);
    setAt(6, SEAT_Y + 8, 5, woodFence);
    setAt(5, SEAT_Y + 5, 5, "minecraft:chain[axis=y]");
    setAt(5, SEAT_Y + 4, 5, "minecraft:iron_bars");

    // Lean-to Dining Shelter (North-West)
    for (let y = baseY; y <= SEAT_Y + 4; y++) {
      setAt(2, y, 2, woodLog);
      setAt(2, y, 5, woodLog);
    }
    for (let z = 2; z <= 5; z++) {
      setAt(2, SEAT_Y + 5, z, makeStair(roofStairs, flipX ? "west" : "east"));
      setAt(3, SEAT_Y + 4, z, roofSlab);
    }

    // Long Dining Trestle Table
    for (let x = 4; x <= 7; x++) {
      setAt(x, baseY, 8, woodSlab);
      setAt(x, baseY, 7, makeStair(woodStairs, "north"));
    }

    // Stacked Provisions & Broken Jars
    setAt(8, baseY, 3, "minecraft:hay_block[axis=y]");
    setAt(8, baseY, 4, "minecraft:hay_block[axis=y]");
    setAt(8, baseY + 1, 3, "minecraft:hay_block[axis=y]");
    setAt(7, baseY, 2, "minecraft:barrel[facing=up]");
    setAt(8, baseY, 2, "minecraft:barrel[facing=north]");
    setAt(7, baseY + 1, 2, "minecraft:barrel[facing=up]");
    setAt(8, baseY, 5, stoneWall);

  } else if (archetype === 4) {
    // === ARCHETYPE 4: SIEGE PALISADE & REDOUBT ===
    // Heavy Log Palisade Wall along Z=3
    for (let x = 1; x <= 9; x++) {
      const logH = 3 + ((x * 2) % 3);
      for (let y = baseY; y < baseY + logH; y++) {
        setAt(x, y, 3, woodLog);
      }
      setAt(x, baseY + logH, 3, woodFence);
      setAt(x, baseY, 2, stoneWall); // Front revetment
      setAt(x, baseY + 1, 4, makeStair(woodStairs, "north")); // Rear brace
    }

    // Elevated Sentry Walkway at SEAT_Y+3 (Z=4..5)
    for (let x = 2; x <= 8; x++) {
      setAt(x, SEAT_Y + 3, 5, woodPlanks);
      setAt(x, SEAT_Y + 2, 5, makeLog(woodLog, "x"));
    }
    // Walkway Support Pillars
    setAt(2, baseY, 5, woodLog);
    setAt(5, baseY, 5, woodLog);
    setAt(8, baseY, 5, woodLog);

    // High Watch Spire & Yardarm at (2, 3) (Reaching Y=SEAT_Y+8)
    for (let y = baseY; y <= SEAT_Y + 7; y++) {
      setAt(2, y, 3, woodLog);
    }
    setAt(2, SEAT_Y + 8, 3, woodFence);
    setAt(1, SEAT_Y + 8, 3, woodFence);
    setAt(3, SEAT_Y + 8, 3, woodFence);
    setAt(2, SEAT_Y + 6, 2, woodTrapdoor);
    setAt(2, SEAT_Y + 6, 4, woodTrapdoor);
    setAt(3, SEAT_Y + 7, 3, "minecraft:chain[axis=y]");

    // Sentry Lean-to & Weapon Benches behind wall
    for (let y = baseY; y <= SEAT_Y + 3; y++) {
      setAt(5, y, 8, woodLog);
      setAt(8, y, 8, woodLog);
    }
    for (let x = 5; x <= 8; x++) {
      setAt(x, SEAT_Y + 4, 7, roofSlab);
      setAt(x, SEAT_Y + 4, 8, roofSlab);
    }
    setAt(6, baseY, 7, "minecraft:chest[facing=south]");
    setAt(7, baseY, 7, "minecraft:barrel[facing=up]");
    setAt(4, baseY, 7, woodFence);
    setAt(4, baseY + 1, 7, "minecraft:iron_bars");
    setAt(3, baseY, 7, "minecraft:campfire[lit=false]");

  } else {
    // === ARCHETYPE 5: MYRMIDON BIVOUAC & ARMORY ===
    // Sturdy Gabled Barracks Frame
    const framePosts = [[2, 5], [5, 5], [8, 5], [2, 8], [5, 8], [8, 8]];
    for (const [fx, fz] of framePosts) {
      for (let y = baseY; y <= SEAT_Y + 4; y++) {
        setAt(fx, y, fz, woodLog);
      }
    }
    // Roof Purlins and Ridge
    for (let x = 2; x <= 8; x++) {
      setAt(x, SEAT_Y + 5, 5, makeStair(roofStairs, "north"));
      setAt(x, SEAT_Y + 5, 8, makeStair(roofStairs, "south"));
      setAt(x, SEAT_Y + 6, 6, roofSolid);
      setAt(x, SEAT_Y + 6, 7, roofSolid);
    }
    // Stripped Rafter Holes (Abandoned Feel)
    setAt(3, SEAT_Y + 6, 6, woodFence);
    setAt(6, SEAT_Y + 6, 7, woodFence);

    // Sleeping Pallets inside
    setAt(3, baseY, 7, woodSlab);
    setAt(4, baseY, 7, woodSlab);
    setAt(6, baseY, 7, woodSlab);
    setAt(7, baseY, 7, woodSlab);
    setAt(5, baseY, 7, "minecraft:barrel[facing=north]");

    // Massive Clan Totem Pole at (5, 3) (Reaching Y=SEAT_Y+8)
    for (let y = baseY; y <= SEAT_Y + 7; y++) {
      setAt(5, y, 3, woodLog);
    }
    setAt(5, SEAT_Y + 8, 3, woodFence);
    setAt(4, SEAT_Y + 7, 3, woodFence);
    setAt(6, SEAT_Y + 7, 3, woodFence);
    setAt(4, SEAT_Y + 6, 3, "minecraft:chain[axis=y]");
    setAt(6, SEAT_Y + 6, 3, "minecraft:chain[axis=y]");

    // Quintain Training Target at (8, 3)
    for (let y = baseY; y <= SEAT_Y + 3; y++) {
      setAt(8, y, 3, woodLog);
    }
    setAt(8, SEAT_Y + 3, 2, woodFence);
    setAt(8, SEAT_Y + 3, 4, woodFence);
    setAt(8, SEAT_Y + 4, 3, makeTrapdoor(woodTrapdoor, "north", false, "bottom"));

    // Weapon Maintenance Station & Hearth
    setAt(3, baseY, 3, "minecraft:anvil[facing=north]");
    setAt(2, baseY, 3, stoneWall);
    setAt(2, baseY, 2, "minecraft:cauldron");
    setAt(5, baseY, 2, "minecraft:campfire[lit=false]");
    setAt(5, baseY, 1, "minecraft:coal_block");
    setAt(4, baseY, 2, "minecraft:gravel");
    setAt(6, baseY, 2, "minecraft:gravel");
  }

  // -------------------------------------------------------------------------
  // 3. AMBIENT ENCOUNTER DEBRIS & BATTLEFIELD TRACES
  // -------------------------------------------------------------------------
  // Overturned jars, stray weapon posts, discarded stakes around corners
  if (rng() < 0.7) setAt(1, baseY, 5, stoneWall);
  if (rng() < 0.7) setAt(9, baseY, 5, stoneWall);
  if (rng() < 0.6) setAt(2, baseY, 1, "minecraft:iron_bars");
  if (rng() < 0.6) setAt(8, baseY, 1, "minecraft:iron_bars");

  // Return node-local metadata
  return {
    name: archetypeNames[archetype],
    seatY: SEAT_Y,
    anchors: {
      front: [Math.floor(W / 2), SEAT_Y, 0],
    },
  };
}
